using DomainModel.Models; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DomainModel.Configurations; public class SiteSettingConfiguration:IEntityTypeConfiguration<SiteSetting>{ public void Configure(EntityTypeBuilder<SiteSetting>b){ b.HasKey(x=>x.SiteSettingID); b.Property(x=>x.SiteName).HasMaxLength(150).IsRequired(); b.Property(x=>x.SiteDescription).HasMaxLength(500); b.Property(x=>x.LogoPath).HasMaxLength(500); b.Property(x=>x.FaviconPath).HasMaxLength(500); b.Property(x=>x.FooterText).HasMaxLength(1000); b.Property(x=>x.InstagramUrl).HasMaxLength(500); b.Property(x=>x.TelegramUrl).HasMaxLength(500); b.Property(x=>x.LinkedInUrl).HasMaxLength(500); b.Property(x=>x.DefaultSeoTitle).HasMaxLength(200); b.Property(x=>x.DefaultSeoDescription).HasMaxLength(500); b.Property(x=>x.DefaultSeoKeywords).HasMaxLength(500); }}